<?php require __DIR__.'/../includes/bootstrap.php';require_role(['admin']);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="voyalo-reservations.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Type','ID','Client','Montant FCFA','Statut','Créée le'],';');$sql="SELECT 'hôtel' type,b.id,u.nom,b.prix_total,b.statut,b.created_at FROM room_bookings b JOIN users u ON u.id=b.user_id UNION ALL SELECT 'billet',b.id,u.nom,b.prix_total,b.statut,b.created_at FROM ticket_bookings b JOIN users u ON u.id=b.user_id UNION ALL SELECT 'forfait',b.id,u.nom,b.prix_total,b.statut,b.created_at FROM package_bookings b JOIN users u ON u.id=b.user_id ORDER BY created_at DESC";foreach($pdo->query($sql) as $r)fputcsv($out,$r,';');fclose($out);exit;
